   457→fun test_support_asset_two_groups() {
   458→    use sui::test_scenario;
   459→    use math::float;
   460→
   461→    let mut scenario = test_scenario::begin(@0x1);
   462→    let ctx = scenario.ctx();
   463→
   464→    let mut registry = new_e_mode_registry(ctx);
   465→
   466→    // Create two emode groups
   467→    let group1 = registry.new_emode_group(0, scenario.ctx());
   468→    let group2 = registry.new_emode_group(0, scenario.ctx());
   469→
   470→    assert!(group1 == 0, 0);
   471→    assert!(group2 == 1, 1);
   472→
   473→    // Create params for TestCoinA in group1
   474→    let params_a_g1 = new_emode_params(
   475→        float::from_quotient(80, 100),  // collateral_factor: 0.8
   476→        float::from_quotient(85, 100),  // liquidation_factor: 0.85
   477→        float::from_quotient(5, 100),   // liquidation_incentive: 0.05
