   492→        float::from_quotient(2, 1000),  // flash_loan_fee_rate: 0.002 (different)
   493→        limiter::create_new_limiter_change(3000000000, 86400, 3600), // deposit_limiter: 3B per day (different)
   494→        limiter::create_new_limiter_change(1000000000, 86400, 3600), // borrow_limiter: 1B per day (different)
   495→    );
